const roles={hq:'Coordina la base y su desarrollo.',depot:'Produce y permite recoger recursos.',grants_population:'Aumenta la capacidad de población.',silo:'Amplía la capacidad de almacenamiento.',tower:'Defiende con ataques a distancia.',wall:'Bloquea el paso y protege el recinto.',bunker:'Defensa militar fortificada.',worker:'Recoge recursos y realiza tareas.',harvester:'Puede extraer materiales del entorno.',healer:'Cura unidades aliadas.',mechanic:'Unidad mecánica: sus reglas de reparación difieren de las orgánicas.',ft_flying:'Se desplaza por el aire.',waterborne:'Se desplaza por el agua.',training_queue:'Admite una cola de entrenamiento.',allows_spy:'Permite funciones de espionaje.',decoration:'Objeto decorativo del entorno.',resource:'Yacimiento o recurso recolectable.',wonder:'Maravilla con una función especial.',farm:'Producción asociada a un cultivo.',lost_item:'Objeto relacionado con exploración o rescates.',ft_armored:'Unidad o estructura blindada.',fireman:'Puede apagar incendios.',explosive:'Objeto con comportamiento explosivo.'};
const labels={b:'Edificio / objeto',u:'Unidad',l:'Terreno'},resources={g:'oro',w:'madera',o:'petróleo',s:'acero',c:'cash'};
let catalog=[],atlas,activeId=26,page=0,filtered=[];
function related(value){const ids=Array.isArray(value)?value:String(value??'').split(/[,;]/).map(Number);return ids.filter(id=>Number(id)>0).map(id=>{const i=catalog.find(i=>i.id===Number(id));return i?'<button data-id="'+i.id+'">'+esc(i.name)+'</button>':'';}).join(' ');}
function detail(id){activeId=Number(id);const i=catalog.find(i=>i.id===activeId);if(!i)return;const props=i.properties&&typeof i.properties==='object'?i.properties:{},spec=atlas.assets[i.id],cost=i.costs&&typeof i.costs==='object'?Object.entries(i.costs).map(([k,v])=>v+' '+(resources[k]||k)).join(' · '):'No consta',uses=Object.entries(props).filter(([k,v])=>v&&roles[k]).map(([k])=>roles[k]),training=related(i.trains_ids),upgrade=related(i.upgrades_to);
 const rows=[['Nivel de jugador',i.min_level],['Huella',i.width+' × '+i.height+' casillas'],['Vida',i.life],['Daño / alcance',i.attack+' / '+i.attack_range],['Intervalo de ataque',i.attack_interval+' ms'],['Velocidad',i.velocity],['Población',i.population],['Coste registrado',cost],['Producción base',i.collect+' '+(resources[i.collect_type]||'')],['XP al recoger',i.collect_xp],['Tiempo de construcción',i.build_time+' s'],['Tiempo de entrenamiento',i.training_time+' s']];
 $('#detail').innerHTML=(spec?'<img src="'+spec.thumb+'" alt="'+esc(i.name)+'">':'')+'<p class="eyebrow">ID '+i.id+' · '+labels[i.type]+'</p><h3>'+esc(i.name)+'</h3><p>'+esc(i.group_type||'Sin familia registrada')+'</p><p>'+(uses.length?uses.map(esc).join(' '):'Su comportamiento específico se define en el cliente y sus misiones; estos parámetros no bastan para reproducirlo.')+'</p><table>'+rows.map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+esc(v)+'</td></tr>').join('')+'</table>'+(training?'<h4>Entrena estas unidades</h4><div class="tags">'+training+'</div>':'')+(upgrade?'<h4>Evolución del archivo</h4><div class="tags">'+upgrade+'</div>':'')+'<h4>Propiedades registradas</h4><div class="tags">'+Object.entries(props).filter(([,v])=>v).map(([k])=>'<span>'+esc(k)+'</span>').join('')+'</div><p class="hint">Parámetros del archivo de 2012. El sitio en funcionamiento utiliza otra revisión; sus precios y catálogo pueden variar.</p><a href="'+source+'assets/sprites/'+encodeURIComponent(i.img_name)+'.swf">Película vectorial original</a> · <a href="'+source+'assets/thumbs/'+encodeURIComponent(i.img_name)+'.jpg">Miniatura original</a>';
 for(const b of $('#results').querySelectorAll('[data-id]'))b.setAttribute('aria-pressed',String(Number(b.dataset.id)===activeId));
}
function results(){const q=$('#search').value.trim().toLowerCase(),kind=$('#kind').value;filtered=catalog.filter(i=>(kind==='all'||(kind==='store'?i.in_store===1:i.type===kind))&&(!q||[i.id,i.name,i.group_type,i.img_name].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(filtered.length/24));page=Math.min(page,pages-1);$('#result-count').textContent=filtered.length+' fichas encontradas';$('#results').innerHTML=filtered.slice(page*24,(page+1)*24).map(i=>'<button class="result" data-id="'+i.id+'" aria-pressed="'+(i.id===activeId)+'"><span><b>'+esc(i.name)+'</b><br><small>'+esc(i.group_type)+' · ID '+i.id+'</small></span><small>Nivel '+i.min_level+'</small></button>').join('');$('#page-label').textContent=(page+1)+' / '+pages;$('#previous').disabled=page===0;$('#next').disabled=page===pages-1;}
$('#search').addEventListener('input',()=>{page=0;results();});$('#kind').addEventListener('change',()=>{page=0;results();});$('#previous').onclick=()=>{page--;results();};$('#next').onclick=()=>{page++;results();};document.addEventListener('click',e=>{const b=e.target.closest('[data-id]');if(b)detail(b.dataset.id);});
const canvas=$('#atlas-map'),ctx=canvas.getContext('2d',{alpha:false}),textures=[],camera={x:50,y:50,zoom:.3};let maps=[],map,grid,w=0,h=0,pending=false,start=null,path=[],routeMode=false;
const screen=(x,y)=>({x:w/2+(x-y-camera.x+camera.y)*32*camera.zoom/2,y:h/2+(x+y-camera.x-camera.y)*32*camera.zoom/4});
function point(x,y){const r=canvas.getBoundingClientRect(),sx=(x-r.x-canvas.clientLeft-w/2)/(16*camera.zoom),sy=(y-r.y-canvas.clientTop-h/2)/(8*camera.zoom);return{x:camera.x+(sx+sy)/2,y:camera.y+(sy-sx)/2};}
function diamond(x,y,size,fill,stroke){const pts=[[x,y],[x+size,y],[x+size,y+size],[x,y+size]].map(([x,y])=>screen(x,y));ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function draw(){pending=false;if(!map)return;const dpr=Math.min(devicePixelRatio||1,1.5);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#428dc3';ctx.fillRect(0,0,w,h);let visible=0;
 for(let y=0;y<20;y++)for(let x=0;x<20;x++){const p=screen(x*5,y*5),width=160*camera.zoom;if(p.x+width/2<0||p.x-width/2>w||p.y+width/2<0||p.y>h)continue;const image=textures[map.tiles[y][x]];if(image)ctx.drawImage(image,p.x-width/2-.5,p.y-.5,width+1,width/2+1);visible++;if($('#walkable').checked)diamond(x*5,y*5,5,map.tiles[y][x]===0?'#113e9470':'#6fd54940');}
 if($('#sectors').checked)for(let y=0;y<10;y++)for(let x=0;x<10;x++){const id=y*10+x+1,owned=map.name==='MAP_PLAYER_1'&&[35,36,45,46].includes(id);diamond(x*10,y*10,10,owned?'#ffeb8630':null,owned?'#ffe57c':'#ffffff38');if(camera.zoom>.22){const p=screen(x*10+5,y*10+5);ctx.fillStyle=owned?'#fff0a7':'#ffffffbb';ctx.font='10px Trebuchet MS';ctx.textAlign='center';ctx.fillText(id,p.x,p.y);}}
 if(path.length){ctx.strokeStyle='#ffe080';ctx.lineWidth=3;ctx.beginPath();[start,...path].forEach((v,i)=>{const p=screen(v.x,v.y);i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y);});ctx.stroke();}if(start)diamond(Math.floor(start.x),Math.floor(start.y),1,'#fff2a1','#584b17');canvas.dataset.visibleTiles=visible;canvas.dataset.map=map.name;
}
function schedule(){if(!pending){pending=true;requestAnimationFrame(draw);}}
function fit(){const r=canvas.getBoundingClientRect();w=canvas.clientWidth;h=canvas.clientHeight;const dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);schedule();}
function home(){camera.x=50;camera.y=50;camera.zoom=Math.min(w/3200,h/1600)*.94;schedule();}
function changeMap(){map=maps[Number($('#map-choice').value)];grid=obstacleGrid(100,(x,y)=>map.tiles[Math.floor(y/5)][Math.floor(x/5)]===0);start=null;path=[];$('#map-status').textContent='Escenario '+map.name+' · 10.000 casillas · agua en azul. '+(map.name==='MAP_PLAYER_1'?'Los cuatro sectores iniciales están resaltados.':'');home();}
$('#map-choice').onchange=changeMap;$('#fit').onclick=home;$('#sectors').onchange=schedule;$('#walkable').onchange=schedule;$('#route-mode').onclick=()=>{routeMode=!routeMode;$('#route-mode').setAttribute('aria-pressed',String(routeMode));$('#map-status').textContent=routeMode?'Marca un punto de tierra de salida y luego su destino.':'Arrastra para explorar el mapa.';};
let drag=null,pinch=0;const pointers=new Map();canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()];pinch=Math.hypot(a.x-b.x,a.y-b.y);drag=null;}else drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};});canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],d=Math.hypot(a.x-b.x,a.y-b.y);if(pinch)camera.zoom=Math.max(.08,Math.min(3,camera.zoom*d/pinch));pinch=d;schedule();return;}if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;const dx=(e.clientX-drag.lastX)/(16*camera.zoom),dy=(e.clientY-drag.lastY)/(8*camera.zoom);camera.x-=(dx+dy)/2;camera.y-=(dy-dx)/2;drag.lastX=e.clientX;drag.lastY=e.clientY;schedule();});canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);pinch=0;if(drag&&!drag.moved&&routeMode&&map){const p=point(e.clientX,e.clientY),x=Math.floor(p.x),y=Math.floor(p.y);if(x<0||y<0||x>=100||y>=100||grid.cells[y*100+x])$('#map-status').textContent='Elige tierra firme. Una tropa terrestre no atraviesa el mar.';else if(!start||path.length){start={x:x+.5,y:y+.5};path=[];$('#map-status').textContent='Salida '+x+', '+y+'. Marca el destino.';}else{path=findGridPath(grid,start,[{x,y}])||[];$('#map-status').textContent=path.length?'Ruta terrestre encontrada: '+path.length+' pasos.':'Estos puntos no están conectados por tierra.';}schedule();}drag=null;});canvas.addEventListener('pointercancel',()=>{pointers.clear();drag=null;pinch=0;});canvas.addEventListener('wheel',e=>{e.preventDefault();const before=point(e.clientX,e.clientY);camera.zoom=Math.max(.08,Math.min(3,camera.zoom*Math.exp(-e.deltaY*.001)));const after=point(e.clientX,e.clientY);camera.x+=before.x-after.x;camera.y+=before.y-after.y;schedule();},{passive:false});new ResizeObserver(fit).observe(canvas);
try{const [c,m,a]=await Promise.all(['./reference-data/catalog.json','./reference-data/maps.json','./classic/atlas.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('No se descargó el archivo');return r.json();})));catalog=c.items;maps=m.maps;atlas=a;$('#map-choice').innerHTML=maps.map((m,i)=>'<option value="'+i+'">'+esc(m.name.replace('MAP_','').replaceAll('_',' '))+'</option>').join('');await Promise.all(Array.from({length:30},async(_,i)=>{const img=new Image();img.src='./classic/terrain/'+String(i).padStart(2,'0')+'.webp';await img.decode();textures[i]=img;}));fit();changeMap();results();detail(activeId);}catch{$('#map-status').textContent='No se pudieron cargar los archivos. Vuelve a abrir este visor con conexión.';}
